using namespace std;

int main(){

    int n; cin>>n;

    vector<int> arr(n); for(int&x:arr) cin>>x;

    vector<int> tails;

    for(int v:arr){

        auto it=lower_bound(tails.begin(),tails.end(),v);

        if(it==tails.end()) tails.push_back(v);

        else *it=v;

    }

    cout<<tails.size()<<'\n';

}

